W = 5
H, A, G = "HRM-theorie", "Arbeidsrecht", "Gespreksvoering"

# ---------- HRM-theorie MC ----------
mc("hrm5-h01", W, H, "Twee schoonmakers verschillen sterk in communicatiestijl en houding tegenover autoriteit. Wat voor soort diversiteit is dit?",
   ["Surface-level diversity", "Deep-level diversity", "Biografische diversiteit", "Formele diversiteit"], 1,
   "Deep-level diversity is minder zichtbaar en wordt pas later duidelijk: waarden, werkstijl, communicatiestijl, houding tegenover autoriteit, motivatie en verwachtingen over werk. Surface-level is zichtbaar, zoals leeftijd, geslacht of kleding.")
mc("hrm5-h02", W, H, "Wat zegt de gelijkheids-attractiehypothese?",
   ["Verschillen tussen mensen leiden altijd tot betere besluiten", "Mensen voelen zich aangetrokken tot gelijken en zijn bij hen minder onzeker; gebrek aan gelijkheid is een kiem voor conflict", "Mensen werken het liefst samen met hun leidinggevende", "Contact tussen groepen vermindert altijd vooroordelen"], 1,
   "Volgens de gelijkheids-attractiehypothese zoeken mensen gelijken op. Hoe sterker de band met de wij-groep, hoe meer anderen als zij-groep worden gezien.")
mc("hrm5-h03", W, H, "Welke stap hoort niet bij de sociale identiteitstheorie (SIT)?",
   ["Sociale categorisatie", "Sociale identificatie", "Sociale vergelijking", "Sociale integratie"], 3,
   "De drie stappen zijn sociale categorisatie (mensen in groepen indelen), sociale identificatie (je zelfbeeld ontlenen aan je in-group) en sociale vergelijking (de eigen groep positiever beoordelen dan de out-group).")
mc("hrm5-h04", W, H, "De vaste schoonmakers geven elkaar de makkelijke ruimtes en laten de zware klussen aan de flexkrachten. Hoe heet dit gedrag?",
   ["Out-group denigration", "In-group favoritism", "Stereotypedreiging", "Contacthypothese"], 1,
   "In-group favoritism is de eigen groep bevoordelen. Out-group denigration is de andere groep afwaarderen. Beide komen voort uit sterk wij-zij-denken.")
mc("hrm5-h05", W, H, "Volgens de contacthypothese vermindert contact tussen groepen het wij-zij-denken, maar alleen onder voorwaarden. Welke is zo'n voorwaarde?",
   ["De groepen werken op verschillende locaties", "Gelijke status van de groepen", "Eén groep is duidelijk hoger in rang", "Het contact is vrijblijvend en zonder doel"], 1,
   "Voorwaarden: gelijke status, weerlegde stereotypen, gemeenschappelijke doelen, gelijkheidsbevorderende normen, leidinggevenden die de naleving bewaken, en daadwerkelijk contact.")
mc("hrm5-h06", W, H, "Wie voert de Participatiewet uit?",
   ["Het UWV", "De gemeenten", "De werkgevers", "De Belastingdienst"], 1,
   "Gemeenten voeren de Participatiewet uit, dus er zijn verschillen per gemeente. Het doel is dat iedereen die kan werken mee kan doen, liefst bij een gewone werkgever.")
mc("hrm5-h07", W, H, "Een facility manager geeft in het teamoverleg open toe dat hij een fout heeft gemaakt in de planning. Welk kenmerk van inclusief leiderschap laat hij zien?",
   ["Zichtbare betrokkenheid", "Nederigheid", "Culturele intelligentie", "Bewustzijn van vooroordelen"], 1,
   "Nederigheid is bescheiden zijn over je eigen capaciteiten en fouten toegeven. De zes kenmerken zijn zichtbare betrokkenheid, nederigheid, bewustzijn van vooroordelen, nieuwsgierigheid naar anderen, culturele intelligentie en effectieve samenwerking.")
mc("hrm5-h08", W, H, "Waarom heeft de Participatiewet volgens het college een grote impact op facility management?",
   ["Omdat FM'ers de uitkeringen moeten betalen", "Omdat FM veel uitvoerende functies heeft en aanbestedingen vaak een SROI-eis bevatten", "Omdat de Participatiewet alleen voor facilitaire bedrijven geldt", "Omdat FM'ers de gemeente vertegenwoordigen"], 1,
   "FM kent veel uitvoerende functies (schoonmaak, catering, post, groen) en bij aanbestedingen geldt vaak een verplicht percentage Social Return on Investment. Dat raakt ook aan Inkoop en recht.")

# ---------- Arbeidsrecht MC ----------
mc("hrm5-a01", W, A, "Welke van deze is géén manier waarop een arbeidsovereenkomst eindigt?",
   ["Van rechtswege", "Wederzijds goedvinden", "Ontbinding door de kantonrechter", "Op non-actiefstelling"], 3,
   "De vier manieren zijn: van rechtswege, wederzijds goedvinden, opzegging en ontbinding door de kantonrechter. Bij op non-actiefstelling loopt de arbeidsovereenkomst door, en het loon ook.")
mc("hrm5-a02", W, A, "Een gastvrouw heeft drie contracten van zes maanden gehad, zonder tussenpozen. Ze krijgt een vierde contract voor zes maanden. Wat is het gevolg volgens de ketenregeling (art. 7:668a BW)?",
   ["Het vierde contract is gewoon een tijdelijk contract", "Het vierde contract geldt als contract voor onbepaalde tijd", "Ze moet eerst zes maanden pauze nemen", "Het vierde contract is nietig"], 1,
   "Een contract voor onbepaalde tijd ontstaat bij het vierde contract voor bepaalde tijd, of als de keten langer dan drie jaar duurt. Tussenpozen van zes maanden of korter tellen mee.")
mc("hrm5-a03", W, A, "Het jaarcontract van een conciërge loopt op 1 maart af. Wanneer moet de werkgever hem uiterlijk schriftelijk laten weten of het contract wordt voortgezet (aanzegplicht, art. 7:668 BW)?",
   ["Op de laatste werkdag", "Uiterlijk een maand voor het einde, dus uiterlijk 1 februari", "Uiterlijk drie maanden voor het einde", "Dat hoeft niet bij een tijdelijk contract"], 1,
   "De werkgever moet uiterlijk een maand voor het einde schriftelijk laten weten of het contract wordt voortgezet en onder welke voorwaarden. Gebeurt dat niet of te laat, dan heeft de werknemer recht op een vergoeding (lid 3). De plicht geldt niet bij contracten korter dan zes maanden of zonder kalenderdatum als einde.")
mc("hrm5-a04", W, A, "Een werknemer tekent een beëindigingsovereenkomst (wederzijds goedvinden). Wat geldt er?",
   ["Hij heeft altijd recht op de wettelijke transitievergoeding", "Hij kan binnen 14 dagen zonder reden schriftelijk ontbinden; staat dat niet in de overeenkomst, dan 3 weken", "De overeenkomst mag mondeling", "Het UWV moet de overeenkomst goedkeuren"], 1,
   "Art. 7:670b BW: de beëindigingsovereenkomst moet schriftelijk, en de werknemer heeft bedenktijd. Er is geen wettelijke transitievergoeding; een vergoeding is onderdeel van de onderhandeling. Voor de WW is van belang dat het initiatief bij de werkgever lag en er geen dringende reden is.")
mc("hrm5-a05", W, A, "Voor welke ontslaggronden loopt de route via het UWV?",
   ["Alle ontslaggronden", "Alleen bedrijfseconomische redenen (a-grond) en twee jaar ziekte (b-grond)", "Alleen disfunctioneren en een verstoorde arbeidsrelatie", "Alleen ontslag op staande voet"], 1,
   "Het UWV geeft toestemming voor opzegging alleen bij de a-grond (bedrijfseconomisch, met anciënniteit en afspiegeling) en de b-grond (twee jaar ziekte). Voor de c- tot en met i-gronden, zoals disfunctioneren, ga je naar de kantonrechter (art. 7:671b BW).")
mc("hrm5-a06", W, A, "Een medewerker is 12 jaar in dienst. Wat is de wettelijke opzegtermijn voor de werkgever (art. 7:672 BW, zonder cao-afwijking)?",
   ["1 maand", "2 maanden", "3 maanden", "4 maanden"], 2,
   "Korter dan 5 jaar: 1 maand; 5 tot 10 jaar: 2 maanden; 10 tot 15 jaar: 3 maanden; 15 jaar of langer: 4 maanden. Opzeggen gebeurt tegen het einde van de maand. Na een UWV-procedure gaat de proceduretijd eraf, maar er blijft minimaal een maand over.")
mc("hrm5-a07", W, A, "Welke voorwaarde hoort niet bij een geldig ontslag op staande voet (art. 7:677 BW)?",
   ["Er is een dringende reden", "Er is onverwijld opgezegd", "De reden is onverwijld meegedeeld", "Het UWV heeft toestemming gegeven"], 3,
   "De drie voorwaarden zijn een dringende reden, onverwijlde opzegging (met tijd voor onderzoek) en onverwijlde mededeling van de reden. Het UWV speelt hierbij geen rol.")
mc("hrm5-a08", W, A, "Hoe hoog is de transitievergoeding volgens art. 7:673 BW?",
   ["Een maandsalaris per dienstjaar", "1/3 maandsalaris per dienstjaar, naar rato bij een deel van een jaar, met een maximum", "Altijd een vast bedrag van €5.000", "Een half maandsalaris per dienstjaar vanaf het tiende jaar"], 1,
   "1/3 maandsalaris per dienstjaar, met een wettelijk maximum dat jaarlijks wordt geïndexeerd. De slide noemt nog €84.000; dat bedrag is verouderd (in 2025 al rond €98.000). Zoek het actuele bedrag op.")

# ---------- Gespreksvoering MC ----------
mc("hrm5-g01", W, G, "Wanneer breng je in een slechtnieuwsgesprek de kernboodschap?",
   ["Aan het eind, als je alle argumenten hebt uitgelegd", "Direct, binnen de eerste zinnen", "Pas als de ander vraagt waarom het gesprek is", "Halverwege, na wat small talk"], 1,
   "Fase 1: breng de boodschap direct. Vermijd uitstellen, de ander laten raden, het nieuws in stukjes brengen en veel argumenten vóór de kernboodschap.")
mc("hrm5-g02", W, G, "Welke opening van een slechtnieuwsgesprek is het best?",
   ["'Er zijn wat ontwikkelingen en mogelijk ontstaan er kansen, maar er kunnen ook gevolgen zijn.'", "'Ik heb slecht nieuws. Door de reorganisatie komt jouw huidige functie te vervallen. Of er een passende nieuwe functie voor je is, is nog niet besloten.'", "'Hoe gaat het met je? Lekker weekend gehad?'", "'Je wordt ontslagen, maar dat ligt niet aan jou.'"], 1,
   "Je kondigt het slechte nieuws aan, brengt de kernboodschap, zegt wat vaststaat en wat nog onzeker is. De vage variant wekt valse hoop, en 'je wordt ontslagen' zeg je niet als dat nog niet besloten is.")
mc("hrm5-g03", W, G, "Hoe reflecteer je een gevoel zonder het in te vullen?",
   ["'Je bent woedend.'", "'Ik merk dat dit veel bij je oproept. Klopt het dat je vooral boos bent over hoe dit besluit tot stand is gekomen?'", "'Je moet niet zo boos worden.'", "'Ik snap precies hoe je je voelt.'"], 1,
   "Je brengt het gevoel als hypothese en controleert het. Bruikbare starters: 'Ik zie dat dit je raakt…', 'Het klinkt alsof…', 'Klopt het dat…?'")
mc("hrm5-g04", W, G, "De medewerker wordt boos en begint te schelden. Wat doe je volgens workshop 5?",
   ["Terugvechten en uitleggen dat je gelijk hebt", "Het besluit alsnog bijstellen om de rust te bewaren", "De emotie erkennen en een grens stellen: 'Ik wil naar je luisteren, maar ik wil wel dat we elkaar zonder schelden aanspreken'", "Meteen de positieve kanten van het besluit noemen"], 2,
   "Bij boosheid: niet terugvechten, niet uitgebreid verdedigen, niet bagatelliseren, niet onderhandelen. Wel de emotie erkennen, een grens stellen aan onacceptabel gedrag, de inhoud samenvatten, de kernboodschap vasthouden en zo nodig pauzeren.")
mc("hrm5-g05", W, G, "Welk signaal laat zien dat de ander toe is aan het bespreken van vervolgstappen?",
   ["Hij zwijgt en kijkt naar de grond", "Hij vraagt: 'Wanneer hoor ik meer?'", "Hij zegt boos dat het oneerlijk is", "Hij herhaalt steeds dezelfde vraag over het besluit"], 1,
   "Signalen voor fase 3 zijn vragen als 'Wat betekent dit nu voor mij?', 'Wanneer hoor ik meer?' en 'Wat kan ik nu doen?'. Stilte, boosheid en herhaalde vragen horen bij fase 2: dan vang je eerst de reactie op.")
mc("hrm5-g06", W, G, "Bij een reorganisatie staat vast dat de functie van de medewerker vervalt, maar niet of er een andere functie voor hem is. Wat zeg je?",
   ["'Je wordt ontslagen.'", "'Je huidige functie vervalt. Of er een passende nieuwe functie voor je beschikbaar is, is nog niet bekend.'", "'Maak je geen zorgen, er komt vast iets anders voor je.'", "'Ik mag er nog niets over zeggen.'"], 1,
   "Scheid feiten, besluiten en onzekerheden. Zeg niet 'je wordt ontslagen' als dat nog niet besloten is, en wek ook geen valse hoop.")
mc("hrm5-g07", W, G, "Wat is de kernopdracht bij de voorbereiding van een slechtnieuwsgesprek?",
   ["Een uitgebreide presentatie maken met alle argumenten", "De kernboodschap vooraf formuleren in maximaal twee zinnen", "Een e-mail opstellen die je na het gesprek stuurt", "Bedenken hoe je het besluit kunt verzachten"], 1,
   "Formuleer de kernboodschap in maximaal twee zinnen. Bereid daarnaast voor wat definitief is, wat onzeker is, twee of drie argumenten, wat je mag delen en niet mag beloven, en regel een rustige, privé ruimte met genoeg tijd.")
mc("hrm5-g08", W, G, "De medewerker is na het nieuws erg aangeslagen en nog niet toe aan vervolgstappen. Wat doe je?",
   ["Toch alle procedures doorlopen, dan is het maar gebeurd", "Voorstellen om morgen opnieuw te spreken en intussen de procedure en contactpersonen op een rij zetten", "Het gesprek afbreken zonder afspraak", "Het besluit terugdraaien"], 1,
   "Vervolgstappen bespreek je pas als de ander eraan toe is. Voorbeeld uit de workshop: 'We hoeven dit nu niet allemaal af te ronden. Ik stel voor dat we morgen opnieuw spreken.' Plan altijd een vervolgcontact.")

# ---------- Open vragen ----------
op("hrm5-ho1", W, H, "In je facilitaire team is er wij-zij-denken tussen vaste en flexibele schoonmakers. Verklaar dit met de sociale identiteitstheorie en beschrijf wat je eraan doet, met de contacthypothese.",
   "Sociale identiteitstheorie: sociale categorisatie (mensen worden ingedeeld als 'vast' en 'flex'), sociale identificatie (je ontleent je zelfbeeld en eigenwaarde aan je groep en volgt de normen daarvan) en sociale vergelijking (de eigen groep wordt positiever beoordeeld, met in-group favoritism en out-group denigration). Contacthypothese: persoonlijk contact laat overeenkomsten zien, onder voorwaarden zoals gelijke status, gemeenschappelijke doelen, gelijkheidsbevorderende normen die de leidinggevende bewaakt, en daadwerkelijk contact. Maatregelen: gemengde teams, een gezamenlijke identiteit ('ons facilitair team'), geen stempels, iedereen een stem in het werkoverleg, eilandjes doorbreken.",
   ["Drie stappen van SIT toegepast op de casus", "Contacthypothese met minstens twee voorwaarden", "Minstens twee concrete maatregelen"])
op("hrm5-ho2", W, H, "Wat is het doel van de Participatiewet, waarom heeft die een grote impact op facility management, en wat moet je als facility manager weten en doen als je iemand via deze wet aanneemt?",
   "Doel: iedereen die kan werken krijgt de kans mee te doen, liefst bij een gewone werkgever, met de nadruk op participatie in plaats van alleen inkomensondersteuning. Gemeenten voeren de wet uit. Impact op FM: veel uitvoerende functies (schoonmaak, catering, post, groen) en aanbestedingen met een verplicht SROI-percentage. Weten: loonkostensubsidie, no-riskpolis en jobcoaching. Doen: duidelijkheid en structuur bieden en draagvlak in het team creëren. Het zijn waardevolle, loyale krachten, maar ze vragen een scherp oog voor procesinrichting en mensgerichte coaching.",
   ["Doel van de wet en rol van gemeenten", "Reden voor impact op FM (uitvoerende functies, SROI)", "Wat je moet weten (subsidie, no-riskpolis, jobcoach)", "Wat je moet doen (structuur, draagvlak)"])
op("hrm5-ao1", W, A, "Noem de vier manieren waarop een arbeidsovereenkomst kan eindigen, met het kernartikel. Geef bij elke manier aan of de werknemer in principe recht heeft op een transitievergoeding.",
   "Van rechtswege (art. 7:667 en 7:668a BW): transitievergoeding als het einde op initiatief van de werkgever is (niet voortzetten). Wederzijds goedvinden (art. 7:670b BW): geen wettelijke transitievergoeding, wel onderwerp van onderhandeling. Opzegging (art. 7:671 e.v. BW), met instemming, met UWV-toestemming, in de proeftijd of op staande voet: bij opzegging door de werkgever in principe wel, maar niet bij ernstig verwijtbaar handelen van de werknemer (meestal bij ontslag op staande voet). Ontbinding door de kantonrechter (art. 7:671b BW): op verzoek van de werkgever in principe wel (art. 7:673 lid 1 sub a).",
   ["Vier manieren met juiste artikelen", "Transitievergoeding per manier juist", "Uitzondering ernstig verwijtbaar handelen werknemer genoemd"])
op("hrm5-ao2", W, A, "Leg de ketenregeling (art. 7:668a BW) en de aanzegplicht (art. 7:668 BW) uit. Wat gebeurt er als een werknemer na de einddatum gewoon doorwerkt?",
   "Ketenregeling: er ontstaat een contract voor onbepaalde tijd bij het vierde contract voor bepaalde tijd, of als de keten langer dan drie jaar duurt. Tussenpozen van zes maanden of korter tellen mee. Aanzegplicht: de werkgever moet uiterlijk een maand voor het einde schriftelijk laten weten of het contract wordt voortgezet en onder welke voorwaarden. Dat geldt niet bij een contract korter dan zes maanden of zonder kalenderdatum als einde. Niet of te laat aangezegd: de werknemer heeft recht op een vergoeding. Werkt de werknemer na de einddatum gewoon door, dan is het contract verlengd onder dezelfde voorwaarden en voor dezelfde duur.",
   ["Ketenregeling: vierde contract of langer dan drie jaar, tussenpozen tot zes maanden", "Aanzegplicht: een maand van tevoren, schriftelijk, uitzonderingen", "Gevolg te laat aanzeggen: vergoeding", "Doorwerken: verlengd onder dezelfde voorwaarden"])
op("hrm5-go1", W, G, "Beschrijf de drie fasen van een slechtnieuwsgesprek en wat je in elke fase doet.",
   "Fase 1, de boodschap direct brengen: kort aankondigen dat je slecht nieuws hebt, de kernboodschap in de eerste zinnen, zeggen wat vaststaat, korte toelichting, dan stoppen en ruimte geven. Fase 2, de reactie opvangen: stilte toelaten, luisteren zonder te verdedigen, de inhoud parafraseren, het gevoel reflecteren als hypothese, controleren, en zo nodig de kernboodschap herhalen. Fase 3, vervolgstappen: pas als de ander eraan toe is; vragen of hij verder wil praten, concrete procedurele informatie geven, realistische mogelijkheden verkennen, afspraken maken en een vervolgcontact plannen.",
   ["Fase 1 juist (direct, vaststaand en onzeker scheiden)", "Fase 2 juist (stilte, parafraseren, gevoel reflecteren)", "Fase 3 juist (pas als de ander eraan toe is, concrete afspraken)"])
op("hrm5-go2", W, G, "Hoe ga je in een slechtnieuwsgesprek om met boosheid? Noem wat je wel en niet doet en formuleer een zin waarmee je een grens stelt.",
   "Niet: terugvechten, jezelf uitgebreid verdedigen, het persoonlijk maken, bagatelliseren, meteen de positieve kanten noemen of alsnog onderhandelen. Wel: de emotie erkennen, een grens stellen aan onacceptabel gedrag, de inhoud samenvatten, de kernboodschap vasthouden en zo nodig pauzeren. Voorbeeld van een grens: 'Ik begrijp dat je boos bent. Ik wil naar je luisteren, maar ik wil wel dat we elkaar zonder schelden blijven aanspreken.'",
   ["Minstens drie dingen die je niet doet", "Minstens drie dingen die je wel doet", "Een respectvolle, duidelijke grenszin"])

# ---------- Casussen ----------
cs("hrm5-hc1", W, H, "Twee groepen in het schoonmaakteam",
   "Je bent facility manager van een ziekenhuis. Het schoonmaakteam bestaat uit vaste medewerkers en flexkrachten. Daarnaast zijn er sinds kort drie medewerkers via de Participatiewet, omdat de laatste aanbesteding een SROI-eis bevatte. In de kantine zitten de groepen apart. Vaste medewerkers zeggen 'de flexers doen maar wat' en de medewerkers via de Participatiewet krijgen vooral de klusjes die niemand wil.",
   [("Verklaar wat er gebeurt met de theorie uit het college.",
     "Sociale identiteitstheorie: categorisatie (vast, flex, Participatiewet), identificatie met de eigen groep en sociale vergelijking, waarbij de eigen groep positiever wordt gezien. Je ziet out-group denigration ('de flexers doen maar wat') en in-group favoritism (de vervelende klusjes gaan naar anderen). De gelijkheids-attractiehypothese verklaart waarom de groepen apart zitten.",
     ["SIT toegepast op de casus", "In-group favoritism en/of out-group denigration herkend"]),
    ("Welke maatregelen neem je? Gebruik de contacthypothese.",
     "Gemengde teams met een gezamenlijk doel, gelijke status in de taakverdeling (rouleren van de zware klussen), duidelijke normen over gelijke behandeling die jij zelf bewaakt, en echt contact, bijvoorbeeld gezamenlijke pauzes of werkoverleggen waarin iedereen een stem krijgt. Spreek van 'ons schoonmaakteam' en vermijd stempels.",
     ["Minstens twee voorwaarden van de contacthypothese vertaald naar maatregelen", "Gezamenlijke identiteit of geen stempels genoemd"]),
    ("Wat heb je nodig om de medewerkers via de Participatiewet goed te laten werken?",
     "Kennis van loonkostensubsidie, no-riskpolis en jobcoaching (de gemeente voert de wet uit). Duidelijkheid en structuur in de taken en het rooster, een jobcoach of vaste begeleider, en draagvlak in het team. Het zijn waardevolle, loyale krachten, maar ze vragen een scherp oog voor procesinrichting en mensgerichte coaching.",
     ["Regelingen genoemd (subsidie, no-riskpolis, jobcoach)", "Structuur en draagvlak in het team"])])
cs("hrm5-ac1", W, A, "Henk na twee jaar ziekte",
   "Henk werkt 12 jaar als technisch medewerker bij een facilitair bedrijf. Hij is nu twee jaar ziek en zal volgens de bedrijfsarts niet in zijn eigen of ander passend werk terugkeren. De werkgever heeft de re-integratie goed gedocumenteerd en wil de arbeidsovereenkomst beëindigen. De UWV-procedure duurt een maand. De werkgever zegt op 10 april 2026 op, direct na de toestemming. Er is geen cao-afwijking.",
   [("Welke ontslagroute moet de werkgever volgen en waar let het UWV op?",
     "Opzegging met toestemming van het UWV (art. 7:671a BW) op de b-grond van art. 7:669 lid 3: twee jaar ziekte. Het UWV controleert onder andere of de re-integratie goed is verlopen. Ook moet herplaatsing binnen een redelijke termijn niet mogelijk zijn (art. 7:669 lid 1). Het opzegverbod tijdens ziekte geldt niet meer na twee jaar.",
     ["UWV-route op de b-grond", "Re-integratie en herplaatsing als toetsingspunten"]),
    ("Wanneer eindigt de arbeidsovereenkomst? Laat je berekening zien.",
     "Bij 12 dienstjaren is de opzegtermijn 3 maanden (art. 7:672 BW). De proceduretijd van een maand gaat eraf, er blijft minimaal een maand over: 2 maanden. Opzeggen gebeurt tegen het einde van de maand: 10 april plus 2 maanden is 10 juni, dus het contract eindigt op 30 juni 2026.",
     ["Opzegtermijn 3 maanden", "Aftrek proceduretijd, minimaal een maand", "Einde van de maand: 30 juni 2026"]),
    ("Heeft Henk recht op een transitievergoeding?",
     "Ja. Bij opzegging door de werkgever is de transitievergoeding verschuldigd (art. 7:673 lid 1 sub a BW): 1/3 maandsalaris per dienstjaar, met een maximum. De werkgever kan bij ontslag na twee jaar ziekte compensatie aanvragen bij het UWV.",
     ["Ja, art. 7:673 lid 1 sub a", "Hoogte 1/3 maandsalaris per dienstjaar", "Compensatie voor de werkgever genoemd"])])
cs("hrm5-gc1", W, G, "De functie van Marco vervalt",
   "Je bent facility manager bij een gemeente. Door een reorganisatie vervalt de functie van Marco, coördinator postkamer, omdat de post wordt gedigitaliseerd. Vast staat: zijn functie vervalt per 1 juli. Nog niet vast: of er een passende andere functie voor hem is. Marco is acht jaar in dienst en kreeg vorige maand nog een goede beoordeling. Je hebt een gesprek met hem in een rustige ruimte.",
   [("Formuleer de kernboodschap waarmee je het gesprek opent.",
     "Bijvoorbeeld: 'Marco, ik heb slecht nieuws. Door de digitalisering van de post vervalt jouw functie als coördinator postkamer per 1 juli. Of er een passende andere functie voor je is, is nog niet bekend.' Daarna stop je en geef je ruimte.",
     ["Kondigt slecht nieuws aan en brengt het direct", "Scheidt wat vaststaat van wat onzeker is", "Geen valse hoop en niet 'je wordt ontslagen'"]),
    ("Marco reageert boos: 'Ik heb vorige maand nog een goede beoordeling gekregen! Dit is belachelijk.' Hoe reageer je?",
     "Niet verdedigen of onderhandelen. Stilte toelaten, dan parafraseren en het gevoel reflecteren: 'Je hebt net een goede beoordeling gehad en dan krijg je dit te horen. Ik kan me voorstellen dat dat onrechtvaardig voelt. Klopt dat?' Erken zijn goede werk, maar houd de kernboodschap vast: het besluit gaat over de functie, niet over zijn prestaties.",
     ["Parafrase en gevoelsreflectie als hypothese", "Erkenning zonder het besluit te veranderen", "Kernboodschap vastgehouden"]),
    ("Marco vraagt: 'Wat betekent dit nu voor mij?' Hoe ga je verder?",
     "Dat is het signaal dat hij toe is aan vervolgstappen. Geef concrete procedurele informatie (de herplaatsingsprocedure, wanneer hij meer hoort, wie zijn contactpersoon is), verken realistische mogelijkheden zonder toezeggingen te doen, maak een afspraak en plan een vervolgcontact, bijvoorbeeld over een week.",
     ["Signaal voor fase 3 herkend", "Concrete informatie en realistische mogelijkheden zonder beloftes", "Vervolgafspraak gepland"])])
